/**
 * The single string-canonicalization rule (verified in the hcl2json spike):
 * hcl2json returns string values with standard escapes decoded (\n, \" are
 * real characters) but template introducers still doubled ($${, %%{). Our
 * model stores the LOGICAL string (single ${ / %{); render re-doubles them.
 * Encode/decode are inverses — property-tested.
 */
/**
 * hcl2json string value → logical string.
 * Callback replacements throughout: in a replacement STRING, `$$` is an
 * escape sequence (so "$${" would silently collapse to "${").
 */
export function decodeTemplateEscapes(s) {
    return s.replaceAll("$${", () => "${").replaceAll("%%{", () => "%{");
}
/** Logical string → HCL template-safe form (inverse of decode). */
export function encodeTemplateEscapes(s) {
    return s.replaceAll("${", () => "$${").replaceAll("%{", () => "%%{");
}
/**
 * Render a logical string as an HCL2 quoted string literal.
 * JSON string escaping is a subset of HCL2's quoted-string escapes
 * (\n, \t, \", \\, \uXXXX are all valid HCL); template introducers are
 * additionally doubled so they stay literal.
 */
export function quoteHclString(logical) {
    return JSON.stringify(encodeTemplateEscapes(logical));
}
